import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the versioned golden vectors generated by color_matching.
///
/// The fixture is intentionally checked in rather than fetched during tests so
/// parity is deterministic and can be reviewed alongside solver changes.
final class WeightedSquaredErrorParityTests: XCTestCase {
    func testMatchesVersionOneCorpusExactly() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertFalse(corpus.scenarios.isEmpty)

        for scenario in corpus.scenarios {
            assertParity(for: scenario)
        }
    }

    private func assertParity(for scenario: ParityScenario, file: StaticString = #filePath, line: UInt = #line) {
        let weights = ChannelWeights(channels: scenario.weights)
        let target = TargetResponseVector(scenario.target.channels.lightingValues)
        let candidates = scenario.palette.map(ParityCandidate.paletteColor)
        let scorer = WeightedSquaredErrorScorer()
        let actualScores = candidates.map { scorer.score(candidate: $0, target: target, weights: weights) }

        XCTAssertEqual(actualScores.count, scenario.expected.scores.count, scenario.id, file: file, line: line)
        for (actual, expected) in zip(actualScores, scenario.expected.scores) {
            switch (actual, expected.score) {
            case (.excluded, .excluded):
                break
            case (.score(let actual), .number(let expected)):
                XCTAssertEqual(actual, expected, accuracy: 0, scenario.id, file: file, line: line)
            default:
                XCTFail("\(scenario.id): score at index \(expected.index) disagrees", file: file, line: line)
            }
        }

        let selectedIndex = actualScores.enumerated()
            .compactMap { index, result -> (Int, Double)? in
                guard case .score(let score) = result else { return nil }
                return (index, score)
            }
            .min { $0.1 < $1.1 }?
            .0

        XCTAssertEqual(selectedIndex, scenario.expected.selectedIndex, scenario.id, file: file, line: line)
        XCTAssertEqual(selectedIndex.flatMap { candidates[$0].hex }, scenario.expected.selectedHexColor, scenario.id, file: file, line: line)
        XCTAssertEqual(selectedIndex.flatMap { actualScores[$0].score }, scenario.expected.error, scenario.id, file: file, line: line)
        XCTAssertEqual(
            scenario.expected.tiedIndices.first,
            scenario.expected.selectedIndex,
            "\(scenario.id): corpus ties must select the earliest candidate",
            file: file,
            line: line
        )
    }

    private func loadCorpus() throws -> ParityCorpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/solver-parity-v1.json")
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: fixture))
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let palette: [ParityCandidate]
    let target: ParityCandidate
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityCandidate: Decodable {
    let hexColor: String
    let channels: [String: Double]

    func paletteColor(index: Int) -> PaletteColor {
        PaletteColor(
            id: index,
            hex: hexColor,
            rgb: RGBColor(hex: hexColor)!,
            responses: channels.lightingValues.mapValues(IlluminationResponse.init(brightness:))
        )
    }
}

private struct ParityExpectation: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

private enum ParityScoreValue: Decodable {
    case number(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
        }
    }
}

private extension Dictionary where Key == String, Value == Double {
    var lightingValues: [LightingCondition: Double] {
        reduce(into: [:]) { values, entry in
            guard let condition = LightingCondition(rawValue: entry.key) else { return }
            values[condition] = entry.value
        }
    }
}

private extension ChannelWeights {
    init(channels: [String: Double]) {
        self.init(
            white: channels["white"] ?? 0,
            red: channels["red"] ?? 0,
            green: channels["green"] ?? 0,
            blue: channels["blue"] ?? 0,
            lps: channels["lps"] ?? 0
        )
    }
}

private extension ScorerResult {
    var score: Double? {
        guard case .score(let value) = self else { return nil }
        return value
    }
}
